var WK_FRANCE = [
  {"id": "france-soupe-a-loignon", "name": "Soupe à l'Oignon", "nameAlt": "French Onion Soup", "aliases": ["French Onion Soup"], "course": "starter", "type": ["starter","soup"], "diet": ["vegetarian"], "cuisine": "western-europe", "country": "France", "region": "Paris / nationwide", "occasion": ["everyday","comfort"], "ingredients": "350g yellow onions (thinly sliced) · 15g butter · 5ml olive oil · 300ml beef stock (or a rich vegetable stock) · 30ml dry sherry or white wine · 1 sprig thyme · 1 slice baguette (30g) · 40g Gruyère (grated) · salt · black pepper", "method": "What separates a great onion soup from a grey, watery one is patience with the onions — and there is no shortcut. Melt the butter with the oil over LOW heat, add the onions and a pinch of salt, and cook them slowly for 45–60 minutes, stirring often, until they collapse into a deep mahogany jam. Rush this on high heat and they brown without ever turning sweet — you will taste the difference in the bowl. When they are dark and glossy, pour in the sherry and scrape every sticky brown fleck off the base; that caramelised layer is pure flavour. Add the stock, thyme and a good grind of pepper, and simmer 20–30 minutes so the two marry. Season carefully. Toast the baguette dry (so it won't turn to mush), pile it with Gruyère and grill until it blisters and bubbles. Float the cheese-toast on the soup and serve while the strands still stretch.", "cookTime": "1 hr 30 min (mostly hands-off)", "kcal": "~500–600 kcal", "nutrition": "Carbs 40g, Fat 35g, Protein 20g; high in calcium", "storage": "Fridge 3–4 days (without the toast). Freezes 3 months. Add a fresh cheese-toast when you reheat.", "chefNotes": "The onions ARE the soup — colour them slowly and deeply, and don't crowd the pan. A splash of brandy at the end lifts the whole thing. For a meat-free bowl, a dark mushroom or onion stock stands in beautifully for the beef.", "pairsWith": "Green Salad with Dijon Vinaigrette · Crusty Baguette", "trivia": "Legend credits King Louis XV, who supposedly threw onions, butter and champagne together late one night at his hunting lodge with nothing else in the pantry. Julia Child later made it a symbol of French cooking abroad.", "howThisFeels": "A bowl that fills the whole house with sweetness — deep, dark and cheese-strung, the taste of a cold night rescued.", "cardHook": "The smell of a cold night rescued", "servings": 1, "sharedWith": ""},
  {"id": "france-bouillabaisse", "name": "Bouillabaisse", "nameAlt": "Provençal Fish Stew", "aliases": [], "course": "main", "type": ["main","soup"], "diet": ["pescatarian"], "cuisine": "western-europe", "country": "France", "region": "Marseille, Provence", "occasion": ["celebration"], "ingredients": "250g mixed firm white fish (cut in chunks) · 100g mussels or prawns · 80g tomatoes (chopped) · 50g onion · 50g fennel · 2 garlic cloves · 200ml fish stock · 30ml white wine · pinch saffron · 10ml olive oil · strip of orange zest · thyme, bay, parsley · salt · pepper · rouille & bread to serve", "method": "Bouillabaisse began as the fishermen's throwaway meal, so the real lesson is confidence, not caviar: what makes it sing is the saffron-and-fennel broth and adding the fish in the right order. Soften the onion, fennel and garlic in the oil without colouring. Add the tomatoes, wine, saffron, orange zest, herbs and stock, and simmer 15 minutes so the broth turns fragrant and golden. Now the order that saves the dish: slide in the firmest fish first, give it a few minutes, then the delicate pieces and shellfish, and cook just until the fish flakes and the mussels open — a hard boil shreds it all to cotton. Serve the broth and fish together with toasted bread and a spoonful of garlicky rouille.", "cookTime": "45–60 min", "kcal": "~350–500 kcal", "nutrition": "Protein 40g, Fat 18g, Carbs 20g; rich in omega-3", "storage": "Fridge 1–2 days (seafood spoils fast). Freeze the broth base up to 2 months and add fresh fish later.", "chefNotes": "Any firm white fish works — use what your fishmonger has fresh; in South Africa kabeljou, kingklip or hake are perfect. Discard any mussels that stay shut. Season last; the broth reduces and concentrates its salt.", "pairsWith": "Rouille · Crusty Baguette · Green Salad with Dijon Vinaigrette", "trivia": "A humble Marseille harbour stew of unsold catch that climbed all the way to white tablecloths — real Marseillais still argue over which fish are allowed in.", "howThisFeels": "Saffron and sea-spray in a bowl — the Mediterranean coast poured out steaming, mopped up with garlic bread.", "cardHook": "The Marseille harbour in a bowl", "servings": 1, "sharedWith": ""},
  {"id": "france-coq-au-vin", "name": "Coq au Vin", "nameAlt": "Chicken Braised in Red Wine", "aliases": [], "course": "main", "type": ["main"], "diet": [], "cuisine": "western-europe", "country": "France", "region": "Burgundy", "occasion": ["celebration","sunday"], "ingredients": "200g bone-in chicken thighs & legs · 30g streaky bacon (cut into lardons) · 100ml red wine (a Burgundy or Pinot Noir) · 100ml chicken stock · 80g button mushrooms (quartered) · 80g baby onions (or chopped onion) · 1 garlic clove · 15g flour · 1 sprig thyme · 1 bay leaf · 10ml oil · salt · black pepper", "method": "A great coq au vin is depth built in layers — and it starts with a wine you'd actually drink, because it reduces right down and its faults concentrate with it. Brown the bacon lardons in the oil until their fat runs, lift them out, then brown the chicken hard in that fat, skin-side first, until deeply golden; this colour is the backbone of the whole sauce, so don't rush or crowd it. Set the chicken aside. Soften the onions, mushrooms and garlic in the same pan, dust with the flour and cook it out for a minute so the sauce won't taste raw. Pour in the wine and scrape up every caramelised scrap, then add the stock, thyme, bay and the bacon. Settle the chicken back in, cover, and simmer very gently — barely a tremble, never a hard boil — for 45–60 minutes, until the meat almost slips from the bone. If the sauce is thin, lift the chicken out and let it reduce until it coats the back of a spoon and gleams.", "cookTime": "1 hr 30 min", "kcal": "~400–500 kcal", "nutrition": "Protein 38g, Fat 22g, Carbs 12g", "storage": "Fridge 3–4 days — it deepens overnight. Freezes 2–3 months. Shred any leftovers through pasta.", "chefNotes": "Brown, don't steam — pieces packed tight in the pan go grey, and colour is everything here. Traditionally made with a whole tough old rooster (the 'coq'), which is why it's slow-cooked; bone-in thighs give you the same richness in a fraction of the time.", "pairsWith": "Buttery Mashed Potatoes · Green Beans Almondine · Crusty Baguette", "trivia": "A Burgundy peasant dish born from stretching a tough old bird with the region's everyday wine — until Julia Child put it on dinner-party tables around the world.", "howThisFeels": "Sunday afternoon in a pot — wine-dark, glossy and unhurried, the kind of smell that makes people wander into the kitchen asking how much longer.", "cardHook": "Sunday afternoon in a pot", "servings": 1, "sharedWith": ""},
  {"id": "france-boeuf-bourguignon", "name": "Bœuf Bourguignon", "nameAlt": "Beef Braised in Red Wine", "aliases": ["Beef Burgundy"], "course": "main", "type": ["main"], "diet": [], "cuisine": "western-europe", "country": "France", "region": "Burgundy", "occasion": ["celebration","sunday"], "ingredients": "200g beef chuck (cubed) · 50g streaky bacon (lardons) · 100ml red wine (Burgundy/Pinot Noir) · 100ml beef stock · 80g carrots (chunks) · 80g mushrooms · 60g baby onions · 1 garlic clove · 15g flour · bouquet garni (thyme, bay, parsley) · 10ml oil · salt · pepper", "method": "The whole secret is in the browning: bœuf bourguignon is only ever as good as the crust you build on the meat before the wine ever touches it. Pat the beef bone-dry and brown it hard in batches — crowd the pan and it steams grey, and grey meat makes grey stew. Render the bacon first and brown the beef in its fat. Set the meat aside, soften the onions, carrots, mushrooms and garlic, then dust in the flour and cook it out a minute. Pour in the wine, scraping up every dark scrap from the base, add the stock, bouquet garni and the beef, and bring to the gentlest simmer. Cover and cook low — oven or stovetop — for 2½–3 hours, until a spoon slides through the meat. If the sauce is thin at the end, uncover and reduce it until it clings and shines.", "cookTime": "3 hr", "kcal": "~450–600 kcal", "nutrition": "Protein 45g, Fat 25g, Carbs 15g", "storage": "Fridge 4 days — genuinely better the next day. Freezes 3 months.", "chefNotes": "Chuck (or shin) is the cut you want — its collagen melts to silk over long cooking, where lean steak just goes dry. Don't rush the browning; it is the flavour. A dark mushroom stock makes a deep meat-free version.", "pairsWith": "Buttery Mashed Potatoes · Gratin Dauphinois · Crusty Baguette", "trivia": "Another Burgundy peasant classic turned icon by Julia Child, whose first American TV episode taught a nation to brown beef properly.", "howThisFeels": "The richest, darkest comfort France owns — wine and beef melted into one glossy spoonful that tastes like a cold Sunday well spent.", "cardHook": "Wine and beef melted into silk", "servings": 1, "sharedWith": ""},
  {"id": "france-blanquette-de-veau", "name": "Blanquette de Veau", "nameAlt": "Creamy White Veal Stew", "aliases": [], "course": "main", "type": ["main"], "diet": [], "cuisine": "western-europe", "country": "France", "region": "Nationwide", "occasion": ["sunday"], "ingredients": "200g veal shoulder (cubed) · 100ml white wine · 150ml veal or chicken stock · 80g mushrooms · 80g baby onions · 50ml cream · 1 egg yolk · 15g butter · 15g flour · squeeze lemon · thyme, bay · salt · white pepper", "method": "A blanquette is the opposite of a brown stew, and that is the whole discipline: you must NOT brown anything, or the ivory colour is lost. Gently blanch the veal, drain, then simmer it softly with the wine, stock and herbs 1–1.5 hours until tender, skimming the top so the broth stays clear. Soften the onions and mushrooms in butter without colour and add them in. Make a pale roux with butter and flour, whisk in the cooking liquor and let it thicken. Now the make-or-break: whisk the cream and egg yolk together, temper them with a ladle of the hot sauce, then stir the lot back off the heat — never let it boil again, or the yolk scrambles and the silk is gone. Finish with a squeeze of lemon to lift the richness.", "cookTime": "2 hr", "kcal": "~450–550 kcal", "nutrition": "Protein 38g, Fat 28g, Carbs 12g", "storage": "Fridge 3 days; reheat gently, never boiling. Freezes 2 months (the sauce may need a fresh whisk).", "chefNotes": "The egg-and-cream liaison goes in off the heat — this is the one rule you cannot break. Chicken or a firm white fish make lighter versions of the same technique.", "pairsWith": "Steamed Rice · Buttered Egg Noodles · Haricots Verts Amandine", "trivia": "A favourite of 19th-century bourgeois tables; the name comes from 'blanc', white — a stew defined by the colour it refuses to lose.", "howThisFeels": "Pale, silky and gentle — the tender, creamy hug of French home cooking, the stew that never raises its voice.", "cardHook": "The stew that never raises its voice", "servings": 1, "sharedWith": ""},
  {"id": "france-cassoulet", "name": "Cassoulet", "nameAlt": "White Bean, Duck & Sausage Casserole", "aliases": [], "course": "main", "type": ["main"], "diet": [], "cuisine": "western-europe", "country": "France", "region": "Languedoc (Toulouse / Castelnaudary)", "occasion": ["celebration","winter"], "ingredients": "100g dried white beans (soaked overnight) · 80g pork sausage (Toulouse-style) · 80g duck confit (1 leg portion) · 50g bacon or pork belly · 80g tomatoes · 50g onion · 2 garlic cloves · 150ml stock · 30g breadcrumbs · thyme, bay · 10ml duck fat or oil · salt · pepper", "method": "Cassoulet is peasant food that rewards patience, and its signature is the crust — the golden skin you break and let re-form on top, over and over. Cook the soaked beans gently with aromatics until just tender but not bursting; they will finish in the oven. Brown the sausage and bacon for colour, then soften the onion, garlic and tomatoes into a rough base. Layer the beans, meats and confit in a deep dish, pour in enough stock to nearly cover, and scatter breadcrumbs over the top. Bake low, around 160°C, for 1½–2 hours; every 20 minutes or so, press the golden crust that forms gently back under the surface with the back of a spoon, and let a new one build. That repeated crust is the soul of the dish — do it a few times and finish uncovered until deep gold.", "cookTime": "3–4 hr (+ overnight soak)", "kcal": "~600–750 kcal", "nutrition": "Protein 40g, Fat 35g, Carbs 45g; high fibre", "storage": "Fridge 3–4 days — even better reheated. Freezes 2–3 months.", "chefNotes": "Tinned white beans save the soak but add them later so they don't collapse. Duck confit is traditional; smoked pork or a good sausage carry the dish honourably if you can't find it. Break and rebuild the crust — that is the ritual.", "pairsWith": "Green Salad with Dijon Vinaigrette · Crusty Baguette", "trivia": "The towns of Toulouse and Castelnaudary have argued for generations over the 'true' cassoulet — named for the cassole, the earthenware pot it bakes in.", "howThisFeels": "A slow winter afternoon you can eat — beans and meat under a burnished crust, the most generous pot in France.", "cardHook": "Beans and meat under a burnished crust", "servings": 1, "sharedWith": ""},
  {"id": "france-steak-frites", "name": "Steak Frites", "nameAlt": "Steak & French Fries", "aliases": [], "course": "main", "type": ["main"], "diet": [], "cuisine": "western-europe", "country": "France", "region": "Paris brasseries / nationwide", "occasion": ["everyday"], "ingredients": "200g sirloin or ribeye steak · 250g potatoes (cut into chips) · 15g butter · 2 garlic cloves · 1 sprig thyme · 10ml oil · oil for frying · salt · black pepper", "method": "Steak frites lives or dies on two separate crusts — one on the steak, one on the chips — and both need dry surfaces and real heat. For frites the secret is frying twice: blanch the cut potatoes in moderate oil (about 160°C) until soft but pale, drain and rest them, then fry again hot (about 190°C) until shatteringly golden; one fry gives you either soft or burnt, never both right. For the steak, take it out of the fridge early — a cold steak steams — pat it bone-dry, season hard, and lay it into a rippingly hot pan. Leave it be to build a crust before turning; then add the butter, garlic and thyme and spoon the foaming butter over for the last minute. Rest the steak five minutes so the juices settle back in, salt the hot chips, and serve.", "cookTime": "40 min", "kcal": "~550–700 kcal", "nutrition": "Protein 35g, Fat 35g, Carbs 45g", "storage": "Best fresh. Reheat leftover chips in a hot oven; slice cold steak for sandwiches.", "chefNotes": "Rest the steak — the single biggest upgrade most home cooks miss. Soaking the cut chips in water first rinses off surface starch for extra crispness. A pat of café-de-Paris or Béarnaise turns it into a feast.", "pairsWith": "Béarnaise Sauce · Aïoli · Green Salad with Dijon Vinaigrette", "trivia": "The unofficial national dish of the Paris brasserie — so standard that many order it simply as 'un steak frites' and trust the kitchen with the rest.", "howThisFeels": "The clatter and chatter of a Paris brasserie — a proper crust, a heap of golden chips, and nothing to prove.", "cardHook": "A Paris brasserie on a plate", "servings": 1, "sharedWith": ""},
  {"id": "france-confit-de-canard", "name": "Confit de Canard", "nameAlt": "Slow-Cooked Duck Leg", "aliases": [], "course": "main", "type": ["main"], "diet": [], "cuisine": "western-europe", "country": "France", "region": "Gascony, South-West France", "occasion": ["celebration"], "ingredients": "1 duck leg (~250g) · enough duck fat to submerge (~300g) · 10g coarse salt · 2 garlic cloves · thyme · 1 bay leaf · black pepper", "method": "Confit is really two crafts in one: a gentle cure and a low, slow poach in fat — and then, right at the end, the part everyone forgets, the crisping. Rub the duck leg with the salt, garlic, thyme and pepper and cure it in the fridge 12–24 hours; this seasons it deep and firms the flesh. Rinse and pat it bone-dry. Submerge it fully in warmed duck fat and cook it very low — around 80–90°C, barely a bubble — for 2.5–3 hours, until the meat surrenders at a fork. It will keep for weeks under its fat. To serve, lift it out, wipe it, and crisp the skin hard in a dry pan, skin-side down, until it crackles — soft confit skin is a sin against the dish.", "cookTime": "3 hr (+ overnight cure)", "kcal": "~500–650 kcal", "nutrition": "Protein 35g, Fat 45g, Carbs 1g", "storage": "Submerged in its fat, fridge for weeks (the original point of confit). Cooked and crisped: 3–4 days.", "chefNotes": "The final crisping in a dry pan is non-negotiable — that is where confit earns its name at the table. Shred leftovers into salads or into a cassoulet. Save the strained fat; it roasts the best potatoes of your life.", "pairsWith": "Lentils · Roast Potatoes · Green Salad with Dijon Vinaigrette", "trivia": "Born as a way to preserve meat through winter before refrigeration — the fat seals out air — and now a proud centrepiece of South-West French cooking.", "howThisFeels": "Skin that shatters over meat that melts — ancient, unhurried and deeply satisfying, France's answer to preserving a feast.", "cardHook": "Skin that shatters, meat that melts", "servings": 1, "sharedWith": ""},
  {"id": "france-poulet-roti", "name": "Poulet Rôti", "nameAlt": "French Roast Chicken", "aliases": [], "course": "main", "type": ["main"], "diet": [], "cuisine": "western-europe", "country": "France", "region": "Nationwide", "occasion": ["sunday","everyday"], "ingredients": "250g bone-in chicken pieces (or a portion of a whole bird) · 20g butter (softened) · 1 garlic clove · 1 sprig thyme · ½ lemon · 10ml oil · salt · black pepper", "method": "The French treat roast chicken as a test of the basics, and they are right — three humble moves make it magnificent. First, dry the skin: pat it bone-dry and, if you have time, leave it uncovered in the fridge an hour, because dry skin is the only skin that crisps. Second, butter under the skin: work softened butter with garlic and thyme directly onto the flesh, so it bastes from the inside. Third, roast it hot to start (around 220°C) to blister the skin, then ease the heat down to cook it through without drying — and tuck a squeezed lemon half alongside to perfume the juices. The real secret, though, is at the end: rest it a full 10 minutes before carving, or all that juice runs out onto the board instead of staying in the meat.", "cookTime": "1 hr 10 min", "kcal": "~450–550 kcal", "nutrition": "Protein 45g, Fat 30g, Carbs 2g", "storage": "Fridge 3 days. Strip the carcass for stock; leftover meat is gold in salads and sandwiches.", "chefNotes": "Rest, rest, rest — a rushed roast chicken bleeds its juices onto the board. Spoon the pan juices over at the table; they are half the point.", "pairsWith": "Roast Potatoes · Haricots Verts Amandine · Gratin Dauphinois", "trivia": "The Sunday-lunch anchor of French homes, so beloved that a good rotisserie chicken from the market is a national comfort in its own right.", "howThisFeels": "Golden skin, thyme and lemon steam — the smell of a French Sunday, the simplest dish that a cook is quietly judged on.", "cardHook": "The smell of a French Sunday", "servings": 1, "sharedWith": ""},
  {"id": "france-moules-marinieres", "name": "Moules Marinières", "nameAlt": "Mussels in White Wine", "aliases": [], "course": "main", "type": ["main"], "diet": ["pescatarian"], "cuisine": "western-europe", "country": "France", "region": "Normandy & Brittany", "occasion": ["everyday"], "ingredients": "500g fresh mussels (in shell) · 50ml dry white wine · 20g shallot (chopped) · 10g garlic · 10g butter · fresh parsley · black pepper · splash cream (optional)", "method": "Moules marinières is a five-minute dish, so everything rides on the mussels being alive and clean and on not overcooking them. Scrub the shells and pull away the wiry beards, and — the safety rule that is also the flavour rule — throw away any mussel that stays open when you tap it, and after cooking any that stay shut. Soften the shallot and garlic in butter without colouring. Pour in the wine and bring it to a fast boil, then tip in the mussels, clap on the lid and steam just 3–5 minutes, shaking the pot once, until the shells gape open. The moment they open they are done; a minute more turns them to rubber. Shower with parsley (and a splash of cream if you like it richer) and serve with bread and the broth to mop.", "cookTime": "20 min", "kcal": "~300–400 kcal", "nutrition": "Protein 28g, Fat 12g, Carbs 12g; rich in iron & zinc", "storage": "Best eaten immediately. Any leftover meat can be picked from the shells for a pasta the next day (fridge 1 day).", "chefNotes": "Buy mussels the day you cook them and keep them cold and loosely covered, never sealed in water. The broth is the treasure — serve it with a spoon and bread.", "pairsWith": "Steak Frites · Crusty Baguette · Aïoli", "trivia": "'Marinière' means sailor-style; on the coast it comes with a mountain of fries as moules-frites, France's happiest cheap feast.", "howThisFeels": "A steaming pot and a pile of empty shells — the sound of the coast, meant to be eaten with your fingers and no ceremony.", "cardHook": "The coast in a steaming pot", "servings": 1, "sharedWith": ""},
  {"id": "france-quiche-lorraine", "name": "Quiche Lorraine", "nameAlt": "Bacon & Egg Custard Tart", "aliases": [], "course": "main", "type": ["main","starter"], "diet": [], "cuisine": "western-europe", "country": "France", "region": "Lorraine", "occasion": ["everyday","brunch"], "ingredients": "80g shortcrust pastry · 40g smoked bacon (lardons) · 30g Gruyère (grated) · 1 egg · 50ml cream · 30ml milk · 20g shallot · pinch nutmeg · black pepper", "method": "A great quiche is all about the custard staying just-set and silky, and the pastry staying crisp — and both come down to two overlooked steps. First, blind-bake the pastry case before it ever meets the filling: line it, weigh it down and bake it pale-gold, or the wet custard will steam it into a soggy base. Second, get the ratio and the heat right — this is a custard, not an omelette. Crisp the bacon and soften the shallot, scatter them and the cheese into the case. Whisk the egg with the cream, milk, nutmeg and pepper (go easy on salt — the bacon and Gruyère carry it) and pour it in. Bake at a gentle 180°C, 30–40 minutes, and pull it while the centre still has a faint wobble — it firms as it cools, and an over-baked quiche turns rubbery and weeps.", "cookTime": "1 hr", "kcal": "~400–550 kcal", "nutrition": "Protein 18g, Fat 32g, Carbs 22g", "storage": "Fridge 3–4 days; reheat in the oven to re-crisp the base. Freezes well.", "chefNotes": "Blind-bake, and don't over-bake — a wobble in the middle means a silky slice once cooled. No added salt in the custard: the smoked bacon and Gruyère bring their own. Classic Lorraine has no cheese at all — Gruyère is the beloved modern addition.", "pairsWith": "Green Salad with Dijon Vinaigrette · Ratatouille", "trivia": "From the Lorraine region on the German border; the word 'quiche' comes from the German 'Kuchen', meaning cake.", "howThisFeels": "Warm, savoury and forgiving — a golden slice that's equally at home at a picnic, a brunch or a Tuesday supper.", "cardHook": "A golden slice for any hour", "servings": 1, "sharedWith": ""},
  {"id": "france-croque-monsieur", "name": "Croque Monsieur", "nameAlt": "Grilled Ham & Cheese with Béchamel", "aliases": ["Croque Madame (version)"], "course": "main", "type": ["main","starter"], "diet": [], "cuisine": "western-europe", "country": "France", "region": "Paris cafés", "occasion": ["everyday","lunch"], "ingredients": "2 slices good white bread · 60g ham · 50g Gruyère (grated) · 100ml béchamel (10g butter, 10g flour, 100ml milk) · 1 tsp Dijon mustard · black pepper · nutmeg", "method": "The croque monsieur is proof that France refuses to phone in even a ham-and-cheese toastie — what lifts it from a snack to a small event is the béchamel, inside and on top. Make a quick béchamel: melt the butter, stir in the flour and cook it a minute so it won't taste of raw paste, then whisk in the milk over the heat until it thickens to a glossy sauce; season with nutmeg and pepper. Toast the bread lightly. Spread one slice with Dijon, layer on ham and half the Gruyère, close the sandwich, then blanket the top with béchamel and the rest of the cheese. Grill until the top blisters deep gold and bubbling. For a Croque Madame — the version named for the ladies — crown it with a fried egg, its runny yolk becoming a second sauce.", "cookTime": "25 min", "kcal": "~450–550 kcal", "nutrition": "Protein 25g, Fat 28g, Carbs 30g", "storage": "Best fresh and hot. Assemble unbaked and fridge up to a day; grill to order.", "chefNotes": "Good bread and real Gruyère are the whole game — no shortcuts hide in something this simple. The Madame (with a fried egg) is the same card, one twist richer.", "pairsWith": "Green Salad with Dijon Vinaigrette · Soupe à l'Oignon", "trivia": "Born in Paris cafés around 1910 as a quick workers' snack; 'croque' means 'crunch', and the Madame supposedly earned her name from the fried egg perched on top like a lady's hat.", "howThisFeels": "The most decadent toasted sandwich in the world — molten, golden and bubbling, a café lunch that eats like a treat.", "cardHook": "The world's most decadent toastie", "servings": 1, "sharedWith": ""},
  {"id": "france-tartiflette", "name": "Tartiflette", "nameAlt": "Potato, Bacon & Reblochon Bake", "aliases": [], "course": "main", "type": ["main"], "diet": [], "cuisine": "western-europe", "country": "France", "region": "Savoie (French Alps)", "occasion": ["winter","comfort"], "ingredients": "250g waxy potatoes · 60g smoked bacon (lardons) · 80g Reblochon (or a soft washed-rind cheese) · 60g onion · 30ml white wine · 30ml cream · 10g butter · black pepper", "method": "Tartiflette is Alpine ski-lodge food, and its whole trick is the cheese: a soft washed-rind round split and laid on top, rind and all, so it melts down into every layer. Parboil the waxy potatoes until just tender, then slice them thick — waxy, not floury, so they hold their shape instead of turning to mash. Fry the bacon and onion until golden and sweet, deglaze with the white wine, and fold in the potatoes and a little cream. Pile it into a dish, then split the Reblochon horizontally and lay the halves cut-side down on top; the rind holds the shape while the inside melts into a river. Bake at 200°C, 20–25 minutes, until the top is bubbling and blistered and the whole thing smells like a mountain. Rest a few minutes so it sets enough to serve.", "cookTime": "50 min", "kcal": "~550–700 kcal", "nutrition": "Protein 22g, Fat 40g, Carbs 40g", "storage": "Fridge 3 days; reheat covered in the oven. Best fresh, though — the cheese is at its glory hot.", "chefNotes": "A soft washed-rind cheese is the heart of it — in South Africa a ripe Camembert or a soft local washed-rind melts beautifully in Reblochon's place. Waxy potatoes only, or it collapses.", "pairsWith": "Green Salad with Dijon Vinaigrette · Cornichons & Charcuterie", "trivia": "Practically invented in the 1980s by the Reblochon cheese board to sell more cheese — and it worked, becoming the definitive dish of the French ski slopes.", "howThisFeels": "A snowy chalet after a cold day — molten cheese, smoky bacon and soft potato, the most comforting bake in the Alps.", "cardHook": "A snowy chalet, melted", "servings": 1, "sharedWith": ""},
  {"id": "france-chateaubriand", "name": "Chateaubriand", "nameAlt": "Roasted Beef Tenderloin (for Two)", "aliases": [], "course": "main", "type": ["main"], "diet": [], "cuisine": "western-europe", "country": "France", "region": "Paris (classic haute cuisine)", "occasion": ["celebration","romantic"], "ingredients": "200g thick-cut beef fillet (centre-cut, per person) · 15g butter · 1 garlic clove · 1 sprig thyme · 10ml oil · salt · black pepper · Béarnaise to serve", "method": "Chateaubriand is a thick centre-cut of fillet, and because that cut is so lean and tender the only real danger is overcooking it — so this is a dish about heat control and resting, not fuss. Take the beef out early and pat it bone-dry; a cold, damp surface will never sear. Season it hard and sear it in a hot pan on every face, including the sides, to build a deep crust all over. Then drop the heat, add butter, garlic and thyme, and either baste it in the foaming butter or finish it in the oven, pulling it at a true medium-rare — a lean cut like this dries out fast past that. Now the discipline: rest it a full 10 minutes under loose foil, then carve it in thick slices across the grain. Classic to the last, it is served for two, carved at the table, with Béarnaise.", "cookTime": "30 min", "kcal": "~450–550 kcal", "nutrition": "Protein 45g, Fat 30g, Carbs 1g", "storage": "Best fresh. Slice any leftovers cold and thin for the finest steak sandwich imaginable.", "chefNotes": "Use a meat thermometer if you have one — for a lean, expensive cut it's cheap insurance against overcooking. Rest it properly; the crust and the rest are the whole dish. Béarnaise is its classic partner (see Sauces).", "pairsWith": "Béarnaise Sauce · Pommes Purée · Haricots Verts Amandine", "trivia": "Named for the 19th-century writer and diplomat François-René de Chateaubriand — a cut, and a dish, built for occasions.", "howThisFeels": "The grand French celebration steak — a thick, tender centre-cut carved at the table for two, all crust and blush and Béarnaise.", "cardHook": "The steak you carve at the table", "servings": 1, "sharedWith": ""},
  {"id": "france-magret-de-canard", "name": "Magret de Canard", "nameAlt": "Seared Duck Breast", "aliases": [], "course": "main", "type": ["main"], "diet": [], "cuisine": "western-europe", "country": "France", "region": "Gascony, South-West France", "occasion": ["celebration"], "ingredients": "1 duck breast (~200g) · salt · black pepper · 1 sprig thyme · optional: 30ml red wine or orange for a quick pan sauce · 10g honey", "method": "A duck breast is really two foods in one — rich fat and lean meat — and the whole art is rendering that fat slowly so it turns to crackling instead of chewy rubber. Score the skin in a criss-cross, cutting through the fat but not into the meat, which lets it render and stops it curling. Season it, then lay it skin-side down into a COLD dry pan and only then turn on the heat — starting cold coaxes the fat out gently. Cook it patiently skin-side down, pouring off the fat as it pools, 6–8 minutes until the skin is thin, deep gold and crisp. Flip it for just a couple of minutes; duck breast is best rosy-pink, and cooked grey it's a waste. Rest it 5 minutes, then carve in thin slices across the grain. A quick sauce from the pan — a splash of wine or orange and a little honey, boiled down — makes it a feast.", "cookTime": "25 min", "kcal": "~400–500 kcal", "nutrition": "Protein 40g, Fat 30g, Carbs 3g", "storage": "Best fresh, cooked pink. Slice leftovers cold into a salad. Save the rendered fat for roast potatoes.", "chefNotes": "Cold pan, skin-side down, then the heat — the single trick that turns duck fat to crackling. Serve it pink; well-done duck breast is dry and grey. Score the skin, not the meat.", "pairsWith": "Gratin Dauphinois · Haricots Verts Amandine · Ratatouille", "trivia": "The magret comes specifically from ducks raised for foie gras, which is why South-West France — the heartland of duck farming — is also the home of this dish.", "howThisFeels": "Restaurant elegance you can pull off at home — crisp mahogany skin over rosy, tender meat, quietly impressive.", "cardHook": "Crisp mahogany over rosy meat", "servings": 1, "sharedWith": ""},
  {"id": "france-steak-tartare", "name": "Steak Tartare", "nameAlt": "Seasoned Raw Beef", "aliases": [], "course": "main", "type": ["main","starter"], "diet": [], "cuisine": "western-europe", "country": "France", "region": "Paris brasseries", "occasion": ["special"], "ingredients": "150g very fresh beef fillet or lean steak (hand-chopped) · 1 egg yolk · 10g shallot (finely diced) · 10g cornichons (chopped) · 5g capers · 5ml Dijon mustard · dash Worcestershire · few drops Tabasco · parsley · salt · black pepper", "method": "Steak tartare is raw beef, so the recipe is really a rule before it is a method: buy the freshest beef you can from a butcher you trust and eat it the same day — that isn't a serving suggestion, it's the whole safety of the dish, exactly as it is with Ethiopia's kitfo. Keep the meat and everything else cold throughout. Chop the beef by hand with a sharp knife into small, even dice — never mince it to paste; the texture is the pleasure. Mix in the shallot, cornichons, capers, mustard, Worcestershire, a drop of Tabasco, parsley, salt and pepper, tasting as you go and adjusting the sharpness and heat to your liking. Shape it lightly, make a small well on top and settle the egg yolk into it, to be stirred through at the table. Serve at once, ice-cold, with hot frites and toast.", "cookTime": "20 min (no cook)", "kcal": "~300–380 kcal", "nutrition": "Protein 35g, Fat 18g, Carbs 4g", "storage": "Eat immediately — this is a same-day, freshly made dish only. Do not store or reheat.", "chefNotes": "Same-day beef from a trusted butcher, kept cold, chopped not minced — that is the recipe, and it is not the place to improvise. If you're at all unsure of the beef, don't make it raw. Not suitable for pregnant people, the very young or anyone advised against raw meat.", "pairsWith": "Steak Frites (the fries) · Crusty Baguette · Green Salad with Dijon Vinaigrette", "trivia": "A brasserie icon whose theatre is the tableside mixing; the raw-yolk-in-a-well presentation is as much a part of it as the beef.", "howThisFeels": "Cool, sharp and daring — clean raw beef woken up with mustard, caper and cornichon, a dish for people who know exactly what they like.", "cardHook": "Clean, cold and daring", "servings": 1, "sharedWith": ""},
  {"id": "france-salade-nicoise", "name": "Salade Niçoise", "nameAlt": "Niçoise Salad", "aliases": [], "course": "starter", "type": ["starter","salad"], "diet": ["pescatarian"], "cuisine": "western-europe", "country": "France", "region": "Nice, Provence", "occasion": ["summer","everyday"], "ingredients": "80g tuna (good tinned, in oil) · 80g new potatoes (boiled) · 60g green beans (blanched) · 1 egg (hard-boiled) · 50g cherry tomatoes · 30g black olives (Niçoise) · 4 anchovy fillets (optional) · mixed leaves · vinaigrette (20ml olive oil, 10ml red wine vinegar, Dijon) · salt · pepper", "method": "A Niçoise is a composed salad, not a tossed one, and that is the whole point: each element is dressed and arranged in its own group so every forkful is a deliberate choice, not a jumble. The real make-or-break is respecting each component — boil the potatoes until just tender, blanch the beans so they stay bright and squeaky, and boil the egg to a just-set yolk, not chalky and grey. Whisk a sharp Dijon vinaigrette. Lay the leaves down, then arrange the potatoes, beans, tomatoes, olives, quartered egg and tuna in their own little zones on top. Drape over the anchovies if using, and spoon the vinaigrette over just before serving so nothing goes soggy. Season lightly — the olives, anchovies and tuna already carry salt.", "cookTime": "30 min", "kcal": "~350–450 kcal", "nutrition": "Protein 25g, Fat 22g, Carbs 22g; rich in omega-3", "storage": "Best assembled fresh. Keep components separately in the fridge up to 2 days and build to order.", "chefNotes": "Buy the best tinned tuna you can — in a spare salad like this, quality has nowhere to hide. No added salt: olives, anchovies and capers season it for you. Purists in Nice argue endlessly over whether potatoes belong at all.", "pairsWith": "Crusty Baguette · Aïoli · Soupe à l'Oignon", "trivia": "From the city of Nice on the Riviera; the truest local versions skip cooked vegetables entirely in high summer, leaning on raw and sun-ripe.", "howThisFeels": "The French Riviera on a plate — sunshine, sea salt and colour, a salad that eats like a whole light lunch.", "cardHook": "The Riviera on a plate", "servings": 1, "sharedWith": ""},
  {"id": "france-escargots", "name": "Escargots à la Bourguignonne", "nameAlt": "Snails in Garlic-Parsley Butter", "aliases": ["Escargot"], "course": "starter", "type": ["starter"], "diet": [], "cuisine": "western-europe", "country": "France", "region": "Burgundy", "occasion": ["special","celebration"], "ingredients": "6 prepared snails (tinned, ~120g) · 40g butter (softened) · 10g garlic (minced) · 10g shallot · 5g parsley (chopped) · 5ml white wine · salt · black pepper · pinch nutmeg · bread to serve", "method": "Here is the honest truth about escargots: the snail is really a vehicle for the garlic-parsley butter, and that butter is where all your attention should go. Mash the softened butter with the garlic, shallot, chopped parsley, wine, salt, pepper and a whisper of nutmeg into a green, fragrant paste — this is the famous beurre d'escargot, and it deserves proper seasoning and really fresh parsley. Tuck a snail into each shell or into the wells of an escargot dish, then top each one generously with the butter, doming it up. Bake hot, around 200°C, for 10–12 minutes until the butter is bubbling furiously and just starting to brown at the edges. Serve immediately, sizzling, with plenty of bread — because mopping up the last of that garlic butter is the best part of the whole dish.", "cookTime": "20 min", "kcal": "~200–300 kcal", "nutrition": "Protein 10g, Fat 24g, Carbs 3g", "storage": "The garlic butter can be made days ahead and even frozen. Cooked snails are best eaten straight away.", "chefNotes": "Don't skimp on the butter or the parsley — they are the dish. Tinned snails (with shells or in a dish) are how nearly everyone makes this at home. The leftover butter is glorious on steak or bread.", "pairsWith": "Crusty Baguette · Steak Frites · Green Salad with Dijon Vinaigrette", "trivia": "A Burgundy classic and a traditional French festive-season starter; the special dimpled dishes and little tongs exist purely for this ritual.", "howThisFeels": "Garlic, butter and a little bravado — a sizzling, old-world starter that's really an excuse to eat garlic bread with a fork.", "cardHook": "An excuse to eat garlic butter", "servings": 1, "sharedWith": ""},
  {"id": "france-gougeres", "name": "Gougères", "nameAlt": "Cheese Choux Puffs", "aliases": [], "course": "starter", "type": ["starter","snack"], "diet": ["vegetarian"], "cuisine": "western-europe", "country": "France", "region": "Burgundy", "occasion": ["party","apero"], "ingredients": "60ml water · 25g butter · 35g flour · 1 egg · 30g Gruyère (grated) · pinch salt · black pepper · pinch nutmeg", "method": "Gougères are savoury choux, and choux only puffs when you get two things right: drying the dough, and adding the eggs slowly. Bring the water and butter to a rolling boil, then tip in all the flour at once and beat hard over the heat until it forms a smooth ball and a thin film coats the base of the pan — this drives off water so the puffs can rise tall and hollow. Cool it a minute, then beat in the egg a little at a time until the dough is glossy and drops reluctantly from the spoon; add it all at once and you'll slacken the batter and get flat puffs. Beat in most of the Gruyère with the pepper and nutmeg. Spoon or pipe walnut-sized mounds, top with the last of the cheese, and bake hot (around 200°C) until deep gold and firm — and don't open the oven early, or they sink. Cooked through and crisp-shelled, they should sound hollow.", "cookTime": "35 min", "kcal": "~250–320 kcal", "nutrition": "Protein 10g, Fat 20g, Carbs 15g", "storage": "Best warm from the oven. Re-crisp in a hot oven; unbaked piped mounds freeze well and bake from frozen.", "chefNotes": "Dry the dough properly and add the egg gradually — the two secrets to a tall, hollow puff. Keep the oven shut until they're set and golden. A little Dijon or cayenne in the dough is a lovely lift.", "pairsWith": "Soupe à l'Oignon · Green Salad with Dijon Vinaigrette", "trivia": "The classic Burgundy apéritif nibble, traditionally handed round with a glass of cold white wine before dinner.", "howThisFeels": "Light, cheesy and impossibly moreish — warm little clouds that vanish two at a time before dinner even starts.", "cardHook": "Warm little cheese clouds", "servings": 1, "sharedWith": ""},
  {"id": "france-ratatouille", "name": "Ratatouille", "nameAlt": "Provençal Vegetable Stew", "aliases": [], "course": "side", "type": ["side","main"], "diet": ["vegan","vegetarian"], "cuisine": "western-europe", "country": "France", "region": "Nice, Provence", "occasion": ["summer","everyday"], "ingredients": "100g aubergine (cubed) · 80g courgette (sliced) · 60g red pepper · 150g tomatoes (chopped) · 50g onion · 2 garlic cloves · 15ml olive oil · thyme · basil · salt · black pepper", "method": "The mistake that turns ratatouille into grey mush is cooking everything together in one pot from the start — the secret the best cooks swear by is to cook each vegetable separately, then bring them together at the end, so each one keeps its own texture and taste. Fry the aubergine in oil until golden and set aside; do the courgette, then the peppers, the same way. Soften the onion and garlic and cook the tomatoes down with thyme into a rich sauce. Now fold everything back together and simmer gently just long enough to marry — 10–15 minutes, no more, so the vegetables stay distinct and bright, not sludgy. Finish with torn basil and a good glug of your best olive oil off the heat. It is even better the next day, warm or at room temperature.", "cookTime": "50 min", "kcal": "~180–250 kcal", "nutrition": "Carbs 22g, Fat 12g, Protein 4g; high fibre & vitamins", "storage": "Fridge 4–5 days — improves overnight. Freezes 3 months. Lovely cold on toast or with eggs.", "chefNotes": "Cook the vegetables separately if you can — it's the difference between a stew that sings and one that sulks. Salting the aubergine first draws out bitterness and stops it drinking oil.", "pairsWith": "Poulet Rôti · Grilled Fish · Crusty Baguette", "trivia": "A Niçoise peasant dish (its name nods to 'touiller', to stir up) that the Pixar film turned into the most famous vegetable stew on earth.", "howThisFeels": "High Provençal summer stewed down soft and glossy — sunshine, herbs and good olive oil in every spoonful.", "cardHook": "Provençal summer, stewed soft", "servings": 1, "sharedWith": ""},
  {"id": "france-gratin-dauphinois", "name": "Gratin Dauphinois", "nameAlt": "Creamy Potato Gratin", "aliases": [], "course": "side", "type": ["side"], "diet": ["vegetarian"], "cuisine": "western-europe", "country": "France", "region": "Dauphiné (French Alps)", "occasion": ["celebration","sunday"], "ingredients": "200g waxy potatoes (thinly sliced) · 80ml cream · 40ml milk · 1 garlic clove (halved) · 30g Gruyère (grated, optional) · butter for the dish · salt · black pepper · pinch nutmeg", "method": "A true gratin dauphinois is defined by what it leaves out as much as what it keeps: no flour, no pre-boiling — the potatoes cook slowly IN the cream, and their own starch is what thickens it into silk. Rub the dish with the cut garlic and butter it well. Slice the potatoes thin and even (a mandoline earns its keep here), and season every layer as you go — under-seasoned potato is bland potato. Pour over the cream and milk mixed with nutmeg, so the liquid just peeps through the top layer. Bake low and slow, around 160–180°C, for 45–60 minutes, until the potatoes are meltingly tender and the top is bronzed and bubbling. The classic Dauphiné version skips the cheese entirely, letting the potato and cream speak; a little Gruyère on top is the popular richer route.", "cookTime": "1 hr 15 min", "kcal": "~280–360 kcal", "nutrition": "Carbs 28g, Fat 22g, Protein 6g", "storage": "Fridge 3–4 days; reheats beautifully in the oven and firms up sliceable-cold.", "chefNotes": "Waxy potatoes and no flour — the starch does the thickening. Slice thin and season every layer. Let it rest 10 minutes out of the oven so it sets enough to cut cleanly.", "pairsWith": "Poulet Rôti · Bœuf Bourguignon · Chateaubriand", "trivia": "From the Dauphiné region in the Alps; 'à la dauphinoise' has come to mean, simply, potatoes baked in cream.", "howThisFeels": "The most luxurious potato in France — layer upon melting layer under a bronzed, bubbling top, pure Sunday indulgence.", "cardHook": "Layer upon melting layer", "servings": 1, "sharedWith": ""},
  {"id": "france-haricots-verts-amandine", "name": "Haricots Verts Amandine", "nameAlt": "Green Beans with Almonds", "aliases": ["Green Beans Almondine"], "course": "side", "type": ["side"], "diet": ["vegetarian"], "cuisine": "western-europe", "country": "France", "region": "Nationwide", "occasion": ["everyday","celebration"], "ingredients": "150g green beans (trimmed) · 20g flaked almonds · 15g butter · 1 garlic clove · squeeze lemon · salt · black pepper", "method": "This simple side goes wrong in exactly one way — overcooked, khaki, sad beans — so the whole skill is stopping them at bright, squeaky, just-tender. Blanch the trimmed beans in well-salted boiling water for just 3–4 minutes, then, and this is the trick that keeps them vivid green, plunge them straight into ice water to stop the cooking dead. Drain them well. Toast the flaked almonds gently in the butter until golden and nutty — watch them, they turn from perfect to burnt in seconds. Add the garlic for a few seconds, then the beans, and toss just to heat through and coat in the nutty butter. Finish with a squeeze of lemon, salt and pepper. Bright, crisp-tender and buttery, with the almonds adding crunch.", "cookTime": "15 min", "kcal": "~150–200 kcal", "nutrition": "Carbs 10g, Fat 12g, Protein 5g; high in vitamin K", "storage": "Blanch the beans ahead and fridge 2 days; do the buttery toss just before serving.", "chefNotes": "The ice-water plunge (refreshing) is what keeps them brilliant green — skip it and they dull and soften. Toast the almonds with one eye on them.", "pairsWith": "Poulet Rôti · Chateaubriand · Magret de Canard", "trivia": "'Amandine' simply means garnished with almonds — one of the most classic and versatile of all French vegetable sides.", "howThisFeels": "Crisp, green and buttery with a nutty crunch — the elegant little side that quietly makes the whole plate look after itself.", "cardHook": "Bright, buttery, nutty crunch", "servings": 1, "sharedWith": ""},
  {"id": "france-creme-brulee", "name": "Crème Brûlée", "nameAlt": "Vanilla Custard with Caramel Top", "aliases": [], "course": "dessert", "type": ["dessert"], "diet": ["vegetarian"], "cuisine": "western-europe", "country": "France", "region": "Nationwide (classic haute cuisine)", "occasion": ["celebration","romantic"], "ingredients": "120ml cream · 1 egg yolk · 20g sugar (for custard) · 5g sugar (for the top) · ½ tsp vanilla (or ¼ vanilla pod) · pinch salt", "method": "Crème brûlée is a study in contrast — cold silky custard under a hot glass-thin crack of caramel — and getting the custard right means treating it gently, because a boiled custard is a scrambled one. Warm the cream with the vanilla until steaming, not boiling. Whisk the yolk with the sugar until pale, then pour the warm cream in slowly while whisking, so the yolk warms gradually instead of curdling. Strain it into a ramekin for glassy smoothness. Bake it in a water bath (a bain-marie) at a low 150–160°C — the water buffers the heat so the custard sets without splitting — until it is set at the edges but still trembles like jelly in the centre. Chill it thoroughly, at least a few hours. Just before serving, sprinkle the top with an even layer of sugar and torch or grill it until it melts to deep amber, then let it harden into that famous brittle sheet.", "cookTime": "50 min (+ chilling)", "kcal": "~300–400 kcal", "nutrition": "Carbs 22g, Fat 28g, Protein 5g", "storage": "Make the custards up to 2–3 days ahead (fridge). Caramelise the tops only just before serving, or they weep and go soft.", "chefNotes": "Low heat and a water bath are the whole secret to a silky, un-scrambled custard. Torch the sugar fresh — a crust made too early softens in the fridge. Pull it from the oven while the middle still wobbles.", "pairsWith": "Fresh Berries · Espresso · Madeleines", "trivia": "Its name means 'burnt cream', and both France and England have claimed it for centuries; the theatrical crack of the spoon through the top is the whole ceremony.", "howThisFeels": "That first crack of the spoon through glassy caramel into cool vanilla silk — the most satisfying two textures in dessert.", "cardHook": "The crack of the spoon through caramel", "servings": 1, "sharedWith": ""},
  {"id": "france-tarte-tatin", "name": "Tarte Tatin", "nameAlt": "Upside-Down Caramel Apple Tart", "aliases": [], "course": "dessert", "type": ["dessert"], "diet": ["vegetarian"], "cuisine": "western-europe", "country": "France", "region": "Loire Valley (Lamotte-Beuvron)", "occasion": ["celebration","autumn"], "ingredients": "150g firm apples (peeled, halved) · 30g sugar · 20g butter · 40g puff pastry · pinch cinnamon (optional) · crème fraîche to serve", "method": "A tarte Tatin is baked upside-down, pastry on top and apples in the caramel below, and the two things that make or break it are the caramel and firm apples that hold their shape. Use apples that stay whole when cooked — soft ones dissolve into sauce. Make a proper caramel in an ovenproof pan: melt the sugar with the butter and let it cook to a real amber, not pale gold, because timid caramel makes a flat, sweet tart while deep caramel brings that bittersweet edge that is the whole point. Pack the apple halves in tightly, cut-side up, over the caramel — they shrink as they cook, so snug is right. Lay the pastry over the top, tucking the edges down inside the pan like a blanket. Bake hot until the pastry is puffed and deep gold. Now the moment of truth: let it settle a few minutes, then invert it confidently onto a plate in one decisive movement, so the caramelised apples end up glistening on top.", "cookTime": "50 min", "kcal": "~300–400 kcal", "nutrition": "Carbs 45g, Fat 16g, Protein 3g", "storage": "Best the day it's baked. Fridge 2 days; warm gently to loosen the caramel before serving.", "chefNotes": "Take the caramel to a proper deep amber and use firm apples — the two non-negotiables. Invert it while still warm and in one brave motion; hesitate and it sticks. A dollop of crème fraîche cuts the sweetness perfectly.", "pairsWith": "Crème Fraîche · Vanilla Ice Cream · Espresso", "trivia": "Supposedly a happy accident by the Tatin sisters in the 1880s, who dropped or overcooked an apple tart and simply served it upside-down — to acclaim.", "howThisFeels": "Burnished, sticky and golden — caramelised apples glistening under buttery pastry, the most charming accident in French baking.", "cardHook": "The most delicious French accident", "servings": 1, "sharedWith": ""},
  {"id": "france-mousse-au-chocolat", "name": "Mousse au Chocolat", "nameAlt": "Classic Chocolate Mousse", "aliases": [], "course": "dessert", "type": ["dessert"], "diet": ["vegetarian"], "cuisine": "western-europe", "country": "France", "region": "Nationwide", "occasion": ["everyday","romantic"], "ingredients": "50g good dark chocolate · 1 egg (separated) · 10g sugar · 10g butter · pinch salt · optional: 5ml strong coffee or orange", "method": "A real French chocolate mousse gets its cloud-like lightness from air, not cream, and there are two moments where that air is won or lost. Melt the chocolate gently with the butter and a pinch of salt — over a bowl of warm water or in short bursts, because chocolate scorched on direct heat turns grainy — then stir in the yolk (and a little coffee or orange, which deepens the chocolate rather than flavouring it). Let it cool to just warm. Meanwhile whisk the egg white with the sugar to soft, glossy peaks. Now the crucial part: fold the whites into the chocolate in additions, gently, with a light hand from underneath — stir hard and you knock out the very air that makes it a mousse and not a pudding. Spoon into glasses and chill at least 2 hours to set. Rich, dark and airy all at once.", "cookTime": "20 min (+ chilling)", "kcal": "~280–350 kcal", "nutrition": "Carbs 22g, Fat 22g, Protein 6g", "storage": "Fridge up to 2–3 days, covered. (Contains raw egg — see notes.)", "chefNotes": "Fold, don't stir — the gentle folding is what keeps it a mousse. Use chocolate you'd happily eat on its own; it's the whole flavour. Note it contains raw egg white, so it's not for pregnant people or the very young.", "pairsWith": "Fresh Berries · Crème Chantilly · Espresso", "trivia": "A French home-cooking staple since the 19th century — the classic version leans on eggs alone, no cream, for its famously light, aerated texture.", "howThisFeels": "Deep, dark and weightless at once — a spoonful of pure chocolate air that feels far more special than how easily it comes together.", "cardHook": "A spoonful of chocolate air", "servings": 1, "sharedWith": ""}
];

